function createToken(user) {
  return {
    sub: user.id,
    iat: Date.now(),
    exp: Date.now() + 3600000
  };
}

test('createToken returns valid token', () => {
  const token = createToken({ id: 1 });
  expect(token).toMatchSnapshot();
});
